/**
 * The irrep engine against spgrep (BSD-3-Clause; fixtures generated by
 * scripts/subgroup-engine/spgrep_fixtures.py, attribution in the fixture's
 * header): for each (space group, k) the characters of every small
 * representation on the little group's operations, and the reality. spgrep
 * puts translations at exp(−2πi k·t), MATERIA at exp(+2πi k·t) (ADR 0003), so
 * MATERIA's characters are the complex conjugates of spgrep's. Characters are
 * compared, never matrices: two correct engines may differ by a change of
 * basis.
 */
import { describe, it, expect } from "vitest";
import { buildSpaceGroup } from "@/core/crystal/spaceGroups";
import { factorGroup } from "@/core/crystal/irreps/factorGroup";
import { irrepsOfStar } from "@/core/crystal/irreps/spaceGroupIrreps";
import { ikey, rmod1, ratFrom, vkey, type RVec } from "@/core/crystal/irreps/rational";
import fixtures from "@/core/crystal/irreps/fixtures/spgrep-small-representations.json";

interface FixtureCase {
  readonly name: string;
  readonly k: readonly number[];
  readonly littleGroup: readonly { readonly rotation: number[][]; readonly translation: string[] }[];
  readonly irreps: readonly { readonly dim: number; readonly indicator: number; readonly characters: readonly (readonly [number, number])[] }[];
}

/** MATERIA's setting for each fixture's space group. */
const SETTING: Record<string, number | string> = {
  "Pm-3m": 221, "Fm-3m": 225, "F-43m": 216, "Fd-3m:2": "F d -3 m:2", "Im-3m": 229, "I4/mmm": 139, "R-3m:H": "R -3 m:H", Cmcm: 63, Pnma: 62, P4: 75,
};

const parseFrac = (s: string): number => {
  const [n, d] = s.split("/");
  return Number(n) / (d === undefined ? 1 : Number(d));
};

describe("small representations agree with spgrep, character by character", () => {
  for (const c of (fixtures as unknown as { cases: FixtureCase[] }).cases) {
    it(c.name, () => {
      const group = factorGroup(buildSpaceGroup(SETTING[c.name.split(" ")[0]!]!).operations);
      const k = [c.k[0]!, c.k[1]!, c.k[2]!] as const;
      const result = irrepsOfStar(group, k);
      // The fixture's little-group operations among MATERIA's elements (same rotation, same translation mod 1).
      const keyOf = (W: readonly (readonly number[])[], t: RVec): string => `${ikey(W as never)}|${vkey(t.map(rmod1) as unknown as RVec)}`;
      const index = new Map(group.elements.map((e, i) => [keyOf(e.W, e.w), i] as const));
      const elements = c.littleGroup.map((op) => {
        const t = op.translation.map((x) => ratFrom(parseFrac(x), 48)) as unknown as RVec;
        const i = index.get(keyOf(op.rotation, t));
        expect(i, `${c.name}: operation ${JSON.stringify(op)} is not in MATERIA's group`).toBeDefined();
        return i!;
      });
      expect(elements).toHaveLength(result.littleCoGroupOrder * group.centrings.length);
      // MATERIA's small representation on g ∈ G_k is the arm-k block of the induced irrep.
      const smallChars = result.irreps.map((irrep) => elements.map((f) => {
        const m = irrep.matrices[f]!;
        let re = 0;
        let im = 0;
        for (let i = 0; i < irrep.smallDim; i++) {
          re += m.re[i * m.n + i]!;
          im += m.im[i * m.n + i]!;
        }
        return [re, im] as const;
      }));
      expect(result.irreps).toHaveLength(c.irreps.length);
      const matched = new Set<number>();
      for (const ref of c.irreps) {
        const hit = result.irreps.findIndex((irrep, j) => !matched.has(j) && irrep.smallDim === ref.dim
          && smallChars[j]!.every(([re, im], f) => Math.abs(re - ref.characters[f]![0]) < 1e-5 && Math.abs(im + ref.characters[f]![1]) < 1e-5));
        expect(hit, `${c.name}: no MATERIA irrep has the conjugate characters of a spgrep small representation of dimension ${ref.dim}`).toBeGreaterThanOrEqual(0);
        matched.add(hit);
        // Reality: for 2k in Λ* (k ≡ −k) the small representation's Frobenius–Schur indicator is the irrep's.
        const twoK = k.map((x) => 2 * x);
        const selfConjugate = twoK.every(Number.isInteger) && group.centrings.every((t) => Number.isInteger(Math.round(1e9 * (twoK[0]! * t[0]!.n / t[0]!.d + twoK[1]! * t[1]!.n / t[1]!.d + twoK[2]! * t[2]!.n / t[2]!.d)) / 1e9));
        if (selfConjugate) {
          const reality = ref.indicator === 1 ? "real" : ref.indicator === -1 ? "pseudoreal" : "complex";
          expect(result.irreps[hit]!.reality, `${c.name}: reality`).toBe(reality);
        }
      }
    });
  }
});
